class Solution {
public:
    vector<int> beautifulArray(int n) {
        vector<int> res = {1};
        while (res.size() < n) {
            vector<int> next;
            for (int x : res) {
                int odd = 2 * x - 1;
                if (odd <= n) next.push_back(odd);
            }
            for (int x : res) {
                int even = 2 * x;
                if (even <= n) next.push_back(even);
            }
            res = next;
        }
        return res;
    }
};
